def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n == 99:
        return 'D'
    last_me, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    if last_me == 'C':
        return 'D'
    cons_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            cons_d += 1
        else:
            break
    if cons_d < 2:
        return 'D'
    start = n - 15
    if start < 0:
        start = 0
    recent_len = n - start
    recent_d = 0
    total_opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            total_opp_d += 1
            if i >= start:
                recent_d += 1
    if total_opp_d == n:
        return 'D'
    if cons_d == 2:
        prob = 0.2
    else:
        prob = 0.1
    if recent_len > 0 and recent_d * 2 <= recent_len and total_opp_d * 2 <= n:
        if cons_d == 2:
            prob = 0.35
        else:
            prob = 0.2
    if rng.random() < prob:
        return 'C'
    return 'D'
